package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.DimensionMismatchException;
import org.apache.commons.math.exception.NotStrictlyPositiveException;
import org.apache.commons.math.exception.OutOfRangeException;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for MultidimensionalCounter.getCounts(int index)
 */
public class MultidimensionalCounter_getCounts_TriageGen1Test {









    @Test
    public void testGetCounts_MiddleElements() {
        // Counter with dimensions 2, 3, 4. Total size = 24
        MultidimensionalCounter counter = new MultidimensionalCounter(2, 3, 4);

        // Index 5: 
        // 5 / (3*4) = 0 (index 0)
        // (5 % 12) / 4 = 1 (index 1)
        // 5 % 4 = 1 (index 2)
        // Expected: {0, 1, 1}
        assertArrayEquals(new int[]{0, 1, 1}, counter.getCounts(5));

        // Index 13:
        // 13 / 12 = 1
        // (13 % 12) / 4 = 0
        // 13 % 4 = 1
        // Expected: {1, 0, 1}
        assertArrayEquals(new int[]{1, 0, 1}, counter.getCounts(13));
    }




}

package org.apache.commons.math.util;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.DimensionMismatchException;
import org.apache.commons.math.exception.NotStrictlyPositiveException;
import org.apache.commons.math.exception.OutOfRangeException;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for MultidimensionalCounter.getCounts(int index)
 */
public class MultidimensionalCounter_getCounts_TriageGen1Test {











    @Test
    public void testGetCounts_SingleDimension() {
        MultidimensionalCounter counter = new MultidimensionalCounter(5);
        // Dimension = 1, last = 0
        // The loop for (i = -1; i < last; i++) will not execute if last is 0
        // indices[0] = index - count; where count is 0
        assertArrayEquals(new int[]{0}, counter.getCounts(0));
        assertArrayEquals(new int[]{2}, counter.getCounts(2));
        assertArrayEquals(new int[]{4}, counter.getCounts(4));
    }


}

package org.apache.commons.math.util;

