import org.apache.commons.math.exception.NotStrictlyPositiveException;
import org.apache.commons.math.exception.OutOfRangeException;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for MultidimensionalCounter.getCounts(int index)
 */
public class MultidimensionalCounter_getCounts_TriageGen1Test {













    @Test
    public void testGetCounts_LargeDimensions() {
        // Test uneven strides and large index
        MultidimensionalCounter counter = new MultidimensionalCounter(10, 10, 10, 10);
        // Index 1234
        // 1234 / 1000 = 1
        // 234 / 100 = 2
        // 34 / 10 = 3
        // 4 % 10 = 4
        assertArrayEquals(new int[]{1, 2, 3, 4}, counter.getCounts(1234));
    }
}
